const svg=$('#setup-svg'), out=$('#setup-out');
const eSl=$('#setup-eps'), eL=$('#setup-eps-lbl'), step=$('#setup-step'), run=$('#setup-run'), reset=$('#setup-reset');
const N=5, GOAL=4;
const pos=[];
for(let s=0;s<N;s++) pos.push([90+s*115, 95]);
// deterministic chain dynamics the AGENT does not know: right -> s+1, left -> s-1 (clamped). reward +1 only on entering GOAL.
// a tiny seeded PRNG so the demo is reproducible (no Math.random nondeterminism in the readout description)
let seed=12345;
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
// running action-value estimates Q[s][a], a in {0:left,1:right}; the agent learns these online (simple incremental average of immediate reward proxy)
let Q, s, steps, total, lastMsg;
function doReset(){ Q=[]; for(let i=0;i<N;i++) Q.push([0,0]); s=0; steps=0; total=0; lastMsg='press a step button'; render(); }
function greedy(st){ return Q[st][1]>=Q[st][0] ? 1 : 0; } // tie -> right
function takeStep(){
  if(s===GOAL){ s=0; } // restart episode at the start state on reaching the goal
  const eps=+eSl.value;
  const explore = rnd()<eps;
  const a = explore ? (rnd()<0.5?0:1) : greedy(s);
  const ns = a===1 ? Math.min(N-1,s+1) : Math.max(0,s-1);
  const r = (ns===GOAL && s!==GOAL) ? 1 : 0;
  // crude online update toward observed reward (illustrative; real value learning is in later sections)
  Q[s][a] += 0.2*(r - Q[s][a]);
  total += r; steps++;
  lastMsg = 'step '+steps+': at s'+s+' chose '+(a===1?'right':'left')+(explore?' (explore)':' (greedy)')+' → s'+ns+', reward '+r;
  s=ns; render();
}
function render(){
  const eps=+eSl.value; eL.textContent='ε = '+eps.toFixed(2);
  svg.innerHTML='';
  // chain edges
  for(let i=0;i<N-1;i++) drawArrow(svg,pos[i],pos[i+1],{color:'var(--line)',markerId:'setup-arrh',width:1.4});
  for(let i=0;i<N;i++){
    const isGoal=i===GOAL, here=i===s;
    drawNode(svg,pos[i][0],pos[i][1],'s'+i,{r:24, fill: here?'var(--panel2)':'var(--panel)', stroke: isGoal?'var(--green)': here?'var(--yellow)':'var(--violet)'});
    const g=greedy(i);
    const t=SVG('text',{x:pos[i][0],y:pos[i][1]+44,'text-anchor':'middle','font-size':11,fill:'var(--cyan)'});
    t.textContent='greedy: '+(g===1?'→':'←'); svg.appendChild(t);
  }
  // agent marker
  svg.appendChild(SVG('circle',{cx:pos[s][0],cy:pos[s][1]-38,r:6,fill:'var(--yellow)'}));
  const gl=SVG('text',{x:pos[GOAL][0],y:pos[GOAL][1]-44,'text-anchor':'middle','font-size':11,fill:'var(--green)'}); gl.textContent='GOAL +1'; svg.appendChild(gl);
  out.textContent =
    'ε = '+eps.toFixed(2)+'    P and R are UNKNOWN to the agent — it only sees sampled (s,a,r,s′)\n'+
    lastMsg+'\n'+
    'agent now at s'+s+'    total reward = '+total+'    over '+steps+' steps\n'+
    'with prob 1−ε take greedy action; with prob ε explore uniformly. Exploration is what lets it discover the goal at all.';
}
ensureArrow(svg,'setup-arrh','var(--line)');
step.addEventListener('click',takeStep);
run.addEventListener('click',()=>{ for(let i=0;i<20;i++) takeStep(); });
reset.addEventListener('click',doReset);
eSl.addEventListener('input',render);
doReset();

const svg=$('#mc-svg'), out=$('#mc-out');
const gSl=$('#mc-gamma'), gL=$('#mc-gamma-lbl'), step=$('#mc-step'), run=$('#mc-run'), reset=$('#mc-reset');
const W=640,H=300, padL=58, padR=24, padT=22, padB=44;
// toy environment: from state s, each episode lasts ~ geometric length, rewards are noisy with mean chosen so true V^pi = 2 at gamma=0.9.
// We generate returns directly with mean Vtrue(gamma) and bounded noise; running mean must converge to Vtrue.
let seed=987654321;
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
function VtrueOf(g){ // a reward of (1-g)*2 received every step forever has return = 2 for all g; we sample noisy versions
  return 2; }
let g, returns, sum;
function doReset(){ g=+gSl.value; returns=[]; sum=0; render(); }
function sampleReturn(){
  // simulate a finite episode: per-step reward = base + noise, base chosen so discounted sum ~ Vtrue
  g=+gSl.value;
  const Vtrue=VtrueOf(g);
  const T=40; const base=(1-g)*Vtrue/(1-Math.pow(g,T)); // per-step reward whose TRUNCATED T-step discounted sum has mean exactly Vtrue (so the running average converges to Vtrue at every γ)
  let G=0, disc=1;
  for(let t=0;t<T;t++){ const r=base + (rnd()-0.5)*0.8; G+=disc*r; disc*=g; }
  returns.push(G); sum+=G; render();
}
function render(){
  g=+gSl.value; gL.textContent='γ = '+g.toFixed(2);
  const Vtrue=VtrueOf(g);
  svg.innerHTML='';
  const n=returns.length;
  const xmax=Math.max(25,n);
  const xs=(i)=> padL + (W-padL-padR)*(i/xmax);
  const vlo=Vtrue-2.2, vhi=Vtrue+2.2;
  const ys=(v)=> padT + (H-padT-padB)*(1-(v-vlo)/(vhi-vlo));
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='return / mean'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='episode #'; svg.appendChild(xl);
  // true value line
  svg.appendChild(SVG('line',{x1:padL,y1:ys(Vtrue),x2:W-padR,y2:ys(Vtrue),stroke:'var(--green)','stroke-width':1.4,'stroke-dasharray':'5 4'}));
  const tv=SVG('text',{x:W-padR,y:ys(Vtrue)-6,'text-anchor':'end','font-size':11,fill:'var(--green)'}); tv.textContent='true V^π = '+Vtrue.toFixed(2); svg.appendChild(tv);
  // sampled returns as dots
  for(let i=0;i<n;i++) svg.appendChild(SVG('circle',{cx:xs(i+1),cy:ys(returns[i]),r:3,fill:'var(--mute)'}));
  // running mean curve
  let path='', running=0;
  for(let i=0;i<n;i++){ running+=returns[i]; const m=running/(i+1); path+=(i?' L':'M')+xs(i+1)+' '+ys(m); }
  if(n>1) svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  for(let i=0,r2=0;i<n;i++){ r2+=returns[i]; svg.appendChild(SVG('circle',{cx:xs(i+1),cy:ys(r2/(i+1)),r:2.5,fill:'var(--yellow)'})); }
  const mean=n? sum/n : 0;
  out.textContent =
    'γ = '+g.toFixed(2)+'    episodes sampled = '+n+'\n'+
    (n? ('latest sampled return Gₜ = '+returns[n-1].toFixed(3)+'    running MC estimate = '+mean.toFixed(3)) : 'press “sample an episode”')+'\n'+
    'true V^π = '+Vtrue.toFixed(2)+'   error |estimate − V^π| = '+(n? Math.abs(mean-Vtrue).toFixed(3):'—')+'\n'+
    'each Gₜ is an unbiased sample of V^π(s); the average converges (LLN), with noise shrinking ~ 1/√n. No model of P or R is used.';
}
step.addEventListener('click',sampleReturn);
run.addEventListener('click',()=>{ for(let i=0;i<25;i++) sampleReturn(); });
reset.addEventListener('click',doReset);
gSl.addEventListener('input',doReset);
doReset();

const svg=$('#td-svg'), out=$('#td-out');
const aSl=$('#td-alpha'), aL=$('#td-alpha-lbl'), method=$('#td-method'), step=$('#td-step'), run=$('#td-run'), reset=$('#td-reset');
const W=640,H=300, padL=58, padR=24, padT=22, padB=44;
const N=5, GOAL=4, gamma=0.9;
// known true V^pi for the fixed policy 'always right' on the chain: reaching GOAL gives +1, gamma-discounted by distance.
// V^pi(s) = gamma^(GOAL-1-s) for s<GOAL (reward +1 on entering GOAL), V(GOAL)=0 (terminal).
const Vtrue=[]; for(let s=0;s<N;s++) Vtrue.push(s<GOAL? Math.pow(gamma,GOAL-1-s):0);
let V, errs, lastMsg;
function err(){ let d=0; for(let s=0;s<GOAL;s++) d=Math.max(d,Math.abs(V[s]-Vtrue[s])); return d; }
function doReset(){ V=new Array(N).fill(0); errs=[err()]; lastMsg='press a run button'; render(); }
function tdSweep(){ const a=+aSl.value;
  // one episode under 'always right' from s0 to GOAL, TD(0) update each transition
  let s=0, last='';
  while(s<GOAL){ const ns=s+1; const r=(ns===GOAL)?1:0; const d=r+gamma*V[ns]-V[s];
    const before=V[s]; V[s]+=a*d; if(s===GOAL-1) last='δ at s'+s+' = '+r+'+'+gamma+'·V(s'+ns+')−V(s'+s+') = '+d.toFixed(3)+'  ⇒ V(s'+s+'): '+before.toFixed(3)+'→'+V[s].toFixed(3); s=ns; }
  errs.push(err()); lastMsg=last; }
function mcSweep(){ const a=+aSl.value;
  // one episode under 'always right'; compute returns then constant-alpha MC update
  const traj=[]; let s=0; while(s<GOAL){ const ns=s+1; const r=(ns===GOAL)?1:0; traj.push([s,r]); s=ns; }
  // returns from each visited state
  let G=0; const Gs=new Array(traj.length);
  for(let i=traj.length-1;i>=0;i--){ G=traj[i][1]+gamma*G; Gs[i]=G; }
  let last='';
  for(let i=0;i<traj.length;i++){ const st=traj[i][0]; const before=V[st]; V[st]+=a*(Gs[i]-V[st]); if(st===GOAL-1) last='Gₜ at s'+st+' = '+Gs[i].toFixed(3)+'  ⇒ V(s'+st+'): '+before.toFixed(3)+'→'+V[st].toFixed(3); }
  errs.push(err()); lastMsg=last; }
function sweep(){ if(method.value==='td') tdSweep(); else mcSweep(); render(); }
function render(){
  const a=+aSl.value; aL.textContent='α = '+a.toFixed(2);
  svg.innerHTML='';
  const e0=Math.max(errs[0],1e-6);
  const xmax=Math.max(30,errs.length-1);
  const xs=(i)=> padL+(W-padL-padR)*(errs.length>1? i/xmax:0);
  const ys=(v)=> padT+(H-padT-padB)*(1-v/e0);
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:H-padB,x2:W-padR,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='‖V−V^π‖∞'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='episode / sweep'; svg.appendChild(xl);
  let path='';
  for(let i=0;i<errs.length;i++) path+=(i?' L':'M')+xs(i)+' '+ys(errs[i]);
  const col= method.value==='td' ? 'var(--yellow)':'var(--cyan)';
  if(errs.length>1) svg.appendChild(SVG('path',{d:path,fill:'none',stroke:col,'stroke-width':2.4}));
  for(let i=0;i<errs.length;i++) svg.appendChild(SVG('circle',{cx:xs(i),cy:ys(errs[i]),r:3,fill:col}));
  const lg=SVG('text',{x:W-padR,y:padT+14,'text-anchor':'end','font-size':11,fill:col}); lg.textContent=(method.value==='td'?'TD(0)':'Monte Carlo')+' error'; svg.appendChild(lg);
  out.textContent =
    'method = '+(method.value==='td'?'TD(0): target r+γV(s′), bootstrapped':'Monte Carlo: target Gₜ, full sampled return')+'    α = '+a.toFixed(2)+'    γ = '+gamma+'\n'+
    'V = ( '+V.map(v=>v.toFixed(3)).join(',  ')+' )      V^π = ( '+Vtrue.map(v=>v.toFixed(3)).join(',  ')+' )\n'+
    lastMsg+'\n'+
    '‖V−V^π‖∞ = '+errs[errs.length-1].toFixed(4)+'    TD has low-variance biased targets; MC has unbiased high-variance targets.';
}
step.addEventListener('click',sweep);
run.addEventListener('click',()=>{ for(let i=0;i<30;i++) sweep(); });
reset.addEventListener('click',doReset);
aSl.addEventListener('input',render);
method.addEventListener('change',doReset);
doReset();

const svg=$('#ql-svg'), out=$('#ql-out');
const eSl=$('#ql-eps'), eL=$('#ql-eps-lbl'), aSl=$('#ql-alpha'), aL=$('#ql-alpha-lbl'), algo=$('#ql-algo'), run=$('#ql-run'), reset=$('#ql-reset');
const N=5, GOAL=4, gamma=0.9;
const pos=[]; for(let s=0;s<N;s++) pos.push([90+s*115,100]);
// actions: 0=left,1=right. deterministic chain. reward +1 on entering GOAL, small step cost -0.02 otherwise.
let seed=2468013579;
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
// true optimal Q*(s,right) ~ gamma^(GOAL-1-s) (minus tiny step costs); the greedy optimum is 'always right'.
let Q, episodes;
function doReset(){ Q=[]; for(let s=0;s<N;s++) Q.push([0,0]); episodes=0; render(); }
function eps(){ return +eSl.value; }
function greedyA(s){ return Q[s][1]>=Q[s][0]?1:0; }
function chooseA(s){ return rnd()<eps() ? (rnd()<0.5?0:1) : greedyA(s); }
function episode(){ const a0lr=+aSl.value, onPolicy=(algo.value==='sarsa');
  let s=0, a=chooseA(s), guard=0;
  while(s<GOAL && guard++<200){ const ns = a===1?Math.min(N-1,s+1):Math.max(0,s-1);
    const r=(ns===GOAL && s!==GOAL)?1:-0.02;
    const na = chooseA(ns);
    let target;
    if(ns===GOAL){ target=r; }
    else if(onPolicy){ target=r+gamma*Q[ns][na]; }
    else { target=r+gamma*Math.max(Q[ns][0],Q[ns][1]); }
    Q[s][a]+= a0lr*(target-Q[s][a]);
    s=ns; a=na; }
  episodes++; }
function render(){
  eL.textContent='ε = '+eps().toFixed(2); aL.textContent='α = '+(+aSl.value).toFixed(2);
  svg.innerHTML='';
  for(let i=0;i<N-1;i++) drawArrow(svg,pos[i],pos[i+1],{color:'var(--line)',markerId:'ql-arrh',width:1.3});
  for(let s=0;s<N;s++){
    const isGoal=s===GOAL, g=greedyA(s);
    drawNode(svg,pos[s][0],pos[s][1],'s'+s,{r:24, fill:'var(--panel2)', stroke:isGoal?'var(--green)':'var(--violet)'});
    if(!isGoal){ const ga=SVG('text',{x:pos[s][0],y:pos[s][1]-34,'text-anchor':'middle','font-size':14,fill:'var(--green)','font-weight':700}); ga.textContent=(g===1?'→':'←'); svg.appendChild(ga); }
    const q=SVG('text',{x:pos[s][0],y:pos[s][1]+44,'text-anchor':'middle','font-size':10.5,fill:'var(--yellow)'});
    q.textContent='Q→'+Q[s][1].toFixed(2)+' Q←'+Q[s][0].toFixed(2); svg.appendChild(q);
  }
  const gl=SVG('text',{x:pos[GOAL][0],y:pos[GOAL][1]-44,'text-anchor':'middle','font-size':11,fill:'var(--green)'}); gl.textContent='GOAL +1'; svg.appendChild(gl);
  const greedyStr=[]; for(let s=0;s<GOAL;s++) greedyStr.push((greedyA(s)===1?'→':'←'));
  out.textContent =
    'algorithm = '+(algo.value==='q'?'Q-learning (off-policy, max over a′)':'SARSA (on-policy, actual a′)')+'    ε = '+eps().toFixed(2)+'    α = '+(+aSl.value).toFixed(2)+'\n'+
    'episodes trained = '+episodes+'    γ = '+gamma+'\n'+
    'greedy policy over s0..s3:  '+greedyStr.join('  ')+'   (optimum is → → → →)\n'+
    'Q(s,right): '+[0,1,2,3].map(s=>Q[s][1].toFixed(3)).join(', ')+'    converges to Q* as a sampled, ε-greedy version of value iteration.';
}
ensureArrow(svg,'ql-arrh','var(--line)');
run.addEventListener('click',()=>{ for(let i=0;i<50;i++) episode(); render(); });
reset.addEventListener('click',doReset);
eSl.addEventListener('input',render);
aSl.addEventListener('input',render);
algo.addEventListener('change',doReset);
doReset();

const svg=$('#fa-svg'), out=$('#fa-out');
const aSl=$('#fa-alpha'), aL=$('#fa-alpha-lbl'), step=$('#fa-step'), run=$('#fa-run'), reset=$('#fa-reset');
const W=640,H=300, padL=58, padR=24, padT=24, padB=46;
const N=6, gamma=0.9;
// true value function along the chain: V*(s) grows toward a goal at the right end. Use V*(s)=gamma^(N-1-s).
const Vtrue=[]; for(let s=0;s<N;s++) Vtrue.push(Math.pow(gamma,N-1-s));
// feature phi(s) = [s/(N-1), 1]; linear value Vhat(s)=w1*phi1 + w0.
function phi(s){ return [s/(N-1), 1]; }
let w, updates;
let seed=314159265;
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
function Vhat(s){ const p=phi(s); return w[0]*p[0]+w[1]*p[1]; }
function doReset(){ w=[0,0]; updates=0; render(); }
function update(){ const a=+aSl.value;
  // pick a random transition s -> s+1 (toward goal); reward 0 except entering goal where target uses Vtrue end value
  const s=Math.floor(rnd()*(N-1)); const ns=s+1;
  const r = (ns===N-1)? (1-gamma)*Vtrue[ns] : 0; // true V = gamma^(N-1-s) is EXPONENTIAL in s, so a linear V-hat cannot represent it exactly — the fit converges to the best linear approximation, not Vtrue
  const target = (ns===N-1)? Vtrue[ns] : r + gamma*Vhat(ns);
  const tderr = target - Vhat(s);
  const p=phi(s);
  w[0]+= a*tderr*p[0]; w[1]+= a*tderr*p[1];
  updates++; }
function render(){
  const a=+aSl.value; aL.textContent='α = '+a.toFixed(2);
  svg.innerHTML='';
  const xs=(s)=> padL+(W-padL-padR)*(s/(N-1));
  const vlo=-0.2, vhi=1.4;
  const ys=(v)=> padT+(H-padT-padB)*(1-(v-vlo)/(vhi-vlo));
  svg.appendChild(SVG('line',{x1:padL,y1:padT,x2:padL,y2:H-padB,stroke:'var(--line)','stroke-width':1}));
  svg.appendChild(SVG('line',{x1:padL,y1:ys(0),x2:W-padR,y2:ys(0),stroke:'var(--line)','stroke-width':1}));
  const yl=SVG('text',{x:padL-8,y:padT+4,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); yl.textContent='value'; svg.appendChild(yl);
  const xl=SVG('text',{x:W-padR,y:H-padB+18,'text-anchor':'end','font-size':11,fill:'var(--mute)'}); xl.textContent='state s'; svg.appendChild(xl);
  // true values (green dots)
  for(let s=0;s<N;s++) svg.appendChild(SVG('circle',{cx:xs(s),cy:ys(Vtrue[s]),r:4.5,fill:'var(--green)'}));
  // linear fit (yellow line) over the chain
  let path='';
  for(let s=0;s<N;s++) path+=(s?' L':'M')+xs(s)+' '+ys(Vhat(s));
  svg.appendChild(SVG('path',{d:path,fill:'none',stroke:'var(--yellow)','stroke-width':2.4}));
  for(let s=0;s<N;s++) svg.appendChild(SVG('circle',{cx:xs(s),cy:ys(Vhat(s)),r:3,fill:'var(--yellow)'}));
  const lg=SVG('text',{x:W-padR,y:padT+14,'text-anchor':'end','font-size':11,fill:'var(--green)'}); lg.textContent='true V (dots)'; svg.appendChild(lg);
  const lg2=SVG('text',{x:W-padR,y:padT+30,'text-anchor':'end','font-size':11,fill:'var(--yellow)'}); lg2.textContent='V̂(s;w) linear fit'; svg.appendChild(lg2);
  let mse=0; for(let s=0;s<N;s++) mse+=Math.pow(Vhat(s)-Vtrue[s],2); mse/=N;
  out.textContent =
    'α = '+a.toFixed(2)+'    semi-gradient TD updates = '+updates+'\n'+
    'weights w = ( slope '+w[0].toFixed(4)+',  bias '+w[1].toFixed(4)+' )   →   one vector covers ALL states\n'+
    'V̂ = ( '+[0,1,2,3,4,5].slice(0,N).map(s=>Vhat(s).toFixed(3)).join(', ')+' )\n'+
    'mean-squared fit error = '+mse.toFixed(5)+'    the true V (dots) is exponential, so the best linear fit cannot match it — the residual is function-approximation error, not a learning bug. Each update moves the whole line (generalization); large α can overshoot.';
}
step.addEventListener('click',()=>{ for(let i=0;i<10;i++) update(); render(); });
run.addEventListener('click',()=>{ for(let i=0;i<200;i++) update(); render(); });
reset.addEventListener('click',doReset);
aSl.addEventListener('input',render);
doReset();

const svg=$('#pg-svg'), out=$('#pg-out');
const lrSl=$('#pg-lr'), lrL=$('#pg-lr-lbl'), base=$('#pg-base'), step=$('#pg-step'), run=$('#pg-run'), reset=$('#pg-reset');
const W=640,H=300, padL=58, padR=24, padT=24, padB=46;
// single-state, two actions: right (reward mean 1) vs left (reward mean 0). softmax over one parameter:
// pi(right)=sigma(theta). J(theta)=pi(right)*1 + pi(left)*0 = sigma(theta). optimum theta->+inf, J->1.
let seed=271828182;
function rnd(){ seed=(seed*1103515245+12345)&0x7fffffff; return seed/0x7fffffff; }
function gauss(){ // Box-Muller, seeded
  let u=rnd()||1e-9, v=rnd(); return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v); }
function sig(x){ return 1/(1+Math.exp(-x)); }
const rMeanRight=1, rMeanLeft=0, noiseSd=0.6;
let theta, Js, steps, Vbaseline;
function doReset(){ theta=0; steps=0; Vbaseline=0; Js=[sig(theta)]; render(); }
function ascentStep(){ const eta=+lrSl.value, useBase=(base.value==='on');
  // sample one action from the softmax, observe noisy reward, form REINFORCE estimator
  const p=sig(theta);
  const a = rnd()<p ? 1 : 0; // 1=right,0=left
  const r = (a===1? rMeanRight: rMeanLeft) + gauss()*noiseSd;
  const b = useBase? Vbaseline : 0;
  // score for softmax over two actions, single param theta on the 'right' logit:
  // d/dtheta log pi(a) = (a - p)
  const score = (a - p);
  const grad = score*(r - b);
